import heapq

EASY_TOPICS = {"combinatorics", "number_theory"}

# Target average sample count for the "easy" topics (combinatorics,
# number_theory), where the verifier score is reliable and the
# average-score-per-answer statistic converges fast. Everything left over
# in the shared pool goes to the "hard" topics (algebra, geometry), where
# the verifier is actively misleading (it tends to agree with the model's
# systematic wrong answer more than with the correct one) so we fall back
# to plain majority vote there, which benefits from more raw samples.
EASY_TARGET_AVG = 5


def _majority_counts(sample_list):
    counts = {}
    for a, _ in sample_list:
        counts[a] = counts.get(a, 0) + 1
    return counts


def _avg_scores(sample_list):
    sums = {}
    cnts = {}
    for a, s in sample_list:
        sums[a] = sums.get(a, 0.0) + s
        cnts[a] = cnts.get(a, 0) + 1
    return {a: sums[a] / cnts[a] for a in sums}


def _margin(agg):
    if not agg:
        return 0.0
    vals = sorted(agg.values(), reverse=True)
    total = sum(abs(v) for v in vals) or 1.0
    if len(vals) == 1:
        return 1.0
    return (vals[0] - vals[1]) / total


def _run_group(env, qids, samples, next_variant, cap, confidence_fn, sub_budget):
    if not qids or sub_budget <= 0:
        return
    n = len(qids)
    phase1 = max(1, min(env.n_variants, sub_budget // n))

    def take(qid):
        if env.left() <= 0:
            return False
        v = next_variant[qid] % env.n_variants
        a, s = env.sample(qid, v)
        samples[qid].append((a, s))
        next_variant[qid] += 1
        return True

    used = 0
    for qid in qids:
        for _ in range(phase1):
            if used >= sub_budget or not take(qid):
                break
            used += 1

    heap = []
    version = {qid: 0 for qid in qids}
    for qid in qids:
        if len(samples[qid]) < cap:
            heapq.heappush(heap, (confidence_fn(samples[qid]), qid, version[qid]))

    while used < sub_budget and env.left() > 0 and heap:
        m, qid, ver = heapq.heappop(heap)
        if ver != version[qid] or len(samples[qid]) >= cap:
            continue
        if not take(qid):
            break
        used += 1
        version[qid] += 1
        if len(samples[qid]) < cap:
            heapq.heappush(heap, (confidence_fn(samples[qid]), qid, version[qid]))

    idx = 0
    while used < sub_budget and env.left() > 0:
        qid = qids[idx % n]
        if not take(qid):
            break
        used += 1
        idx += 1


def run(env):
    questions = env.questions
    n = len(questions)
    budget = env.budget

    easy_qids = [q["id"] for q in questions if q["topic"] in EASY_TOPICS]
    hard_qids = [q["id"] for q in questions if q["topic"] not in EASY_TOPICS]

    samples = {q["id"]: [] for q in questions}
    next_variant = {q["id"]: 0 for q in questions}

    easy_budget = min(budget, EASY_TARGET_AVG * len(easy_qids))
    hard_budget = budget - easy_budget

    def easy_confidence(s):
        return _margin(_avg_scores(s))

    def hard_confidence(s):
        return _margin(_majority_counts(s))

    avg = budget / n if n else 6
    cap = max(3, min(30, int(round(avg * 5))))

    _run_group(env, easy_qids, samples, next_variant, cap, easy_confidence, easy_budget)
    _run_group(env, hard_qids, samples, next_variant, cap, hard_confidence, budget - env.left() - easy_budget + hard_budget if False else (budget - (0)))

    # Spend whatever remains (from rounding, or easy finishing under budget)
    # on hard questions first, then easy, then just anywhere.
    all_qids = hard_qids + easy_qids if hard_qids else easy_qids
    idx = 0
    while env.left() > 0 and all_qids:
        qid = all_qids[idx % len(all_qids)]
        v = next_variant[qid] % env.n_variants
        a, s = env.sample(qid, v)
        samples[qid].append((a, s))
        next_variant[qid] += 1
        idx += 1

    out = {}
    for q in questions:
        qid = q["id"]
        s = samples[qid]
        if not s:
            continue
        if q["topic"] in EASY_TOPICS:
            agg = _avg_scores(s)
        else:
            agg = _majority_counts(s)
        out[qid] = max(agg.items(), key=lambda kv: kv[1])[0]

    env.submit(out)

